public sealed class PlaceOrder(ShopDb db, IMessageBus bus)
{
    public async Task HandleAsync(Order order, CancellationToken ct)
    {
        db.Orders.Add(order);
        await db.SaveChangesAsync(ct); // committed
        // A crash, deploy or broker outage here: the order exists,
        // and no other service will ever hear about it
        await bus.PublishAsync(new OrderPlaced(order.Id, order.Total), ct);
    }
}

using System.Text.Json;

public sealed class PlaceOrder(ShopDb db)
{
    public async Task HandleAsync(Order order, CancellationToken ct)
    {
        var evt = new OrderPlaced(order.Id, order.Total);
        db.Orders.Add(order);
        db.Outbox.Add(new OutboxMessage
        {
            Id = Guid.NewGuid(), // the message id consumers dedupe on
            Type = nameof(OrderPlaced),
            Payload = JsonSerializer.Serialize(evt),
        });
        await db.SaveChangesAsync(ct); // one transaction: both rows or neither
    }
}

