using Microsoft.EntityFrameworkCore;

public sealed class OutboxRelay(ShopDb db, IMessageBus bus)
{
    public async Task PublishPendingAsync(CancellationToken ct)
    {
        var pending = await db.Outbox.Where(m => m.PublishedAt == null)
            .OrderBy(m => m.Sequence) // the order they were written in
            .Take(100).ToListAsync(ct);

        foreach (var m in pending)
        {
            await bus.PublishAsync(m.Id, m.Type, m.Payload, ct);
            // A crash here publishes this row again on the next run
            m.PublishedAt = DateTime.UtcNow;
            await db.SaveChangesAsync(ct);
        }
    }
}
